export interface K2 {
  readonly gardens: {
    /** Every Garden, in order. no cap · local · zen-gardens-v1. e.g. `const gardens = await k2.gardens.list()` */
    list(): Promise<GardenSummary[]>
    /** The Garden on screen. no cap · local · zen-gardens-v1. e.g. `const here = await k2.gardens.current()` */
    current(): Promise<GardenSummary | null>
    /** Show another Garden (at most once every 2 s, never in the first 2 s). no cap · local · zen-gardens-v1. e.g. `await k2.gardens.switch(gardens[1].id)` */
    switch(id: string): Promise<null>
  }
  readonly theme: {
    /** The page's theme: scheme and --zen-* values, the window's chrome table, and reduced motion. no cap · local · zen-v1. e.g. `const {theme, motion} = await k2.theme.get()` */
    get(): Promise<ThemeInfo>
    /** The same value as theme.get, pushed when the theme or motion changes. no cap · local · zen-widgets-v1. e.g. `k2.theme.changed(({theme}) => paint(theme))` */
    changed(cb: (value: ThemeInfo) => void, onError?: (error: K2Error) => void): () => void
    /** Handler object: re-subscribes on its own after a retryable refusal (capped backoff). */
    changed(handlers: K2Handlers<ThemeInfo>): () => void
  }
  readonly canvas: {
    /** Full-canvas Gardens: up to 32 rects (CSS px, this frame's viewport) where clicks reach you through K2's top drag strip; replaces the last list, [] clears. K2's own controls stay on top. no cap · local · zen-widgets-v1. e.g. `await k2.canvas.setHitRegions([bar.getBoundingClientRect()])` */
    setHitRegions(rects: HitRegion[]): Promise<null>
  }
  readonly window: {
    /** Start moving the window, from a mousedown in this widget (only while a button is down here). no cap · local · zen-widgets-v1. e.g. `grip.addEventListener('mousedown', () => k2.window.startDrag())` */
    startDrag(): Promise<null>
  }
  readonly save: {
    /** One of this widget's private saves, or null. This computer only. no cap · local · garden-data-v1. e.g. `const best = await k2.save.get('high-score')` */
    get(key: string): Promise<unknown>
    /** Keep a private value for this widget (agents never see saves). This computer only. no cap · local · garden-data-v1. e.g. `await k2.save.set('high-score', 42)` */
    set(key: string, value: unknown): Promise<null>
    /** Forget one private save. This computer only. no cap · local · garden-data-v1. e.g. `await k2.save.remove('high-score')` */
    remove(key: string): Promise<null>
    /** The keys of this widget's private saves. This computer only. no cap · local · garden-data-v1. e.g. `const keys = await k2.save.keys()` */
    keys(opts?: { prefix?: string }): Promise<string[]>
  }
  readonly viewer: {
    /** Who is looking: the person on this computer, by name. This computer only. no cap · local · garden-data-v1. e.g. `const {name} = await k2.viewer()` */
    get(): Promise<Viewer>
    /** Same as `k2.viewer.get()`. */
    (): Promise<Viewer>
  }
  readonly app: {
    /** This App: its id, live Seed hash, health and when it was deployed (its own App only; the App pass, never a guest). This computer only. no cap · portable · app-self-v1. e.g. `const me = await k2.asApp().app.self()` */
    self(args?: { app?: string }): Promise<AppSelf>
    /** This App's quotas, live use and per-call counts from its own audit (its own App only; the App pass, never a guest). This computer only. no cap · portable · app-self-v1. e.g. `const {verbs, quotas} = await k2.asApp().app.usage({hours: 24})` */
    usage(args?: { app?: string; hours?: number }): Promise<AppUsage>
  }
  readonly widget: {
    /** This widget: its id, live hash, who made it and its last 7 days of use. This computer only. no cap · local · app-self-v1. e.g. `const me = await k2.widget.self()` */
    self(): Promise<WidgetSelf>
    /** The widget's folder name (or k2:<name>), once `connected` resolves. */
    readonly id: string
    readonly name: string
    readonly garden: string
  }
  readonly agents: {
    /** The agents in the widget's scope, with live status. cap agents:read · portable · zen-v1. e.g. `const rows = await k2.agents.list()` */
    list(): Promise<AgentRow[]>
    /** The same rows as agents.list, pushed on every change. cap agents:read · portable · zen-v1. e.g. `const off = k2.agents.subscribe((rows) => draw(rows))` */
    subscribe(cb: (value: AgentRow[]) => void, onError?: (error: K2Error) => void): () => void
    /** Handler object: re-subscribes on its own after a retryable refusal (capped backoff). */
    subscribe(handlers: K2Handlers<AgentRow[]>): () => void
  }
  readonly conversation: {
    /** Show this agent in the built-in Conversation that follows the widget. cap agents:read · local · zen-v1. e.g. `await k2.conversation.open(row.address)` */
    open(address: string): Promise<null>
    /** Clear the widget's pick. cap agents:read · local · zen-v1. e.g. `await k2.conversation.close()` */
    close(): Promise<null>
  }
  readonly presence: {
    /** Other people looking at one agent right now (never you). cap presence:read · local · zen-v1. e.g. `const people = await k2.presence.get(row.address)` */
    get(address: string): Promise<Person[]>
    /** The same list as presence.get, pushed on change. cap presence:read · local · zen-v1. e.g. `const off = k2.presence.subscribe(row.address, (people) => draw(people))` */
    subscribe(address: string, cb: (value: Person[]) => void, onError?: (error: K2Error) => void): () => void
    /** Handler object: re-subscribes on its own after a retryable refusal (capped backoff). */
    subscribe(address: string, handlers: K2Handlers<Person[]>): () => void
  }
  readonly thread: {
    /** A page of the Thread, oldest first; beforeSeq pages back through history. cap thread:read · portable · zen-v1. e.g. `const page = await k2.thread.read(row.address, {limit: 50})` */
    read(address: string, opts?: { beforeSeq?: number; limit?: number }): Promise<ThreadPage>
    /** The live Thread with one agent and its working turn, pushed on every change. cap thread:read · portable · zen-v1. e.g. `const off = k2.thread.subscribe(row.address, (view) => draw(view))` */
    subscribe(address: string, cb: (value: ThreadView) => void, onError?: (error: K2Error) => void): () => void
    /** Handler object: re-subscribes on its own after a retryable refusal (capped backoff). */
    subscribe(address: string, handlers: K2Handlers<ThreadView>): () => void
    /** Send text to the agent as you (text only, no files). cap thread:post · portable · zen-v1. e.g. `await k2.thread.post(row.address, 'How is it going?')` */
    post(address: string, text: string): Promise<Posted>
    /** Answer a choice card in the Thread (never a secret card). cap thread:post · portable · zen-v1. e.g. `await k2.thread.answer(row.address, card.id, 'Yes')` */
    answer(address: string, cardId: string, choice: string): Promise<null>
  }
  readonly compose: {
    /** Set K2's message box for that agent; never sends. cap thread:post · local · zen-v1. e.g. `await k2.compose.draft(row.address, 'Ask for a status')` */
    draft(address: string, text: string): Promise<null>
  }
  readonly sources: {
    /** The sources this placement names, with their state and whether K2 can reach them. cap sources:read · portable · sources-v1. e.g. `const rows = await k2.sources.list()` */
    list(): Promise<SourceListRow[]>
    /** One source's card view; ages come from serverNow minus updatedAt. cap sources:read · portable · sources-v1. e.g. `const v = await k2.sources.read(k2.config.source)` */
    read(address: string): Promise<SourceView>
    /** A field's trend points (gaps as null). cap sources:read · portable · sources-v1. e.g. `const h = await k2.sources.history(k2.config.source, 'count')` */
    history(address: string, field: string, opts?: { fromAt?: number; toAt?: number }): Promise<SourceHistory>
    /** The card view, pushed on every change (counts toward the 16 subscriptions). cap sources:read · portable · sources-v1. e.g. `const off = k2.sources.subscribe(k2.config.source, (v) => draw(v))` */
    subscribe(address: string, cb: (value: SourceView) => void, onError?: (error: K2Error) => void): () => void
    /** Handler object: re-subscribes on its own after a retryable refusal (capped backoff). */
    subscribe(address: string, handlers: K2Handlers<SourceView>): () => void
    /** Ask the source's server to check now (at most once every 15 seconds). cap sources:read · portable · sources-v1. e.g. `await k2.sources.refresh(k2.config.source)` */
    refresh(address: string): Promise<SourceRefresh>
    /** Open K2's Ask an agent box about this source (K2 writes the draft; nothing is sent). cap sources:read · local · sources-v1. e.g. `await k2.sources.ask(k2.config.source, tile.key)` */
    ask(address: string, itemKey?: string | null): Promise<SourceAsk>
  }
  readonly store: {
    /** One key of this widget's data (or, with {from}, of a widget it reads), or null. This computer only. cap store:read · local · garden-data-v1. e.g. `const e = await k2.store.get('obj/7')` */
    get(key: string, opts?: { from?: string }): Promise<StoreEntry | null>
    /** Keys in order, a page at a time (at most 500 and 60 KiB). This computer only. cap store:read · local · garden-data-v1. e.g. `const {items, next} = await k2.store.list({prefix: 'obj/'})` */
    list(opts?: { after?: string; from?: string; limit?: number; prefix?: string }): Promise<StorePage>
    /** Changes after a cursor, whole revs at a time (subscribe uses this). This computer only. cap store:read · local · garden-data-v1. e.g. `const page = await k2.store.changes({since: 41})` */
    changes(opts: { after?: string; from?: string; prefix?: string; since: number }): Promise<StoreChanges>
    /** Save one key; with ifRev, only if nobody changed it since. This computer only. cap store:write · local · garden-data-v1. e.g. `const {rev} = await k2.store.put('obj/7', note, {ifRev: e.rev})` */
    put(key: string, value: unknown, opts?: { ifRev?: number }): Promise<StoreRev>
    /** Delete one key (a missing key is not an error). This computer only. cap store:write · local · garden-data-v1. e.g. `await k2.store.delete('obj/7')` */
    delete(key: string, opts?: { ifRev?: number }): Promise<StoreDeleted>
    /** Up to 64 writes, all or nothing, as one rev. This computer only. cap store:write · local · garden-data-v1. e.g. `await k2.store.batch([{op: 'put', key: 'obj/1', value: a}, {op: 'delete', key: 'obj/2'}])` */
    batch(ops: StoreOp[]): Promise<StoreCommit>
    /** Open a transaction (k2.store.tx() wraps begin, add and commit). This computer only. cap store:write · local · garden-data-v1. e.g. `const tx = k2.store.tx()` */
    txBegin(): Promise<StoreTx>
    /** Stage up to 64 more writes (1,000 and 1 MiB in all); nothing is visible until commit. This computer only. cap store:write · local · garden-data-v1. e.g. `await tx.add(ops)` */
    txAdd(txId: string, ops: StoreOp[]): Promise<StoreTxStatus>
    /** Apply every staged write as one rev, or none of them. This computer only. cap store:write · local · garden-data-v1. e.g. `const {rev} = await tx.commit()` */
    txCommit(txId: string): Promise<StoreCommit>
    /** Drop a transaction's staged writes. This computer only. cap store:write · local · garden-data-v1. e.g. `await tx.abort()` */
    txAbort(txId: string): Promise<StoreTxAborted>
    /** Live changes under a prefix, from any writer (you, this widget, agents). The first delivery is the whole current state, then one per rev (never half of one). `since` resumes after a rev you have. Counts toward the 16 live subscriptions. This computer only. */
    subscribe(prefix: string | { prefix?: string; since?: number; from?: string }, cb: (delivery: StoreDelivery) => void, onError?: (error: K2Error) => void): () => void
    /** Handler object: re-subscribes on its own after a retryable refusal; a delivery that isn't a StoreDelivery reaches `error` as bad_shape. */
    subscribe(prefix: string | { prefix?: string; since?: number; from?: string }, handlers: K2Handlers<StoreDelivery>): () => void
    /** A transaction: add op parts (1,000 ops and 1 MiB in all), then commit them as one rev, or abort. This computer only. */
    tx(): StoreTxHandle
    /** Save text over 60 KiB (at most 1 MiB) as parts `<key>/~0`… plus a header at `<key>`, in one transaction. This computer only. */
    putChunked(key: string, text: string, opts?: { ifRev?: number }): Promise<StoreCommit>
    /** Read a putChunked value back (null when missing). A part that doesn't match fails with reason chunk_mismatch. This computer only. */
    getChunked(key: string): Promise<string | null>
  }
  readonly guests: {
    /** One of this App's guests: its rooms on this App and its role (App: its own guests; Garden: any local App's). This computer only. cap guests:rooms · portable · guests-rooms-v1. e.g. `const g = await k2.asApp().guests.rooms({username: 'dana'})` */
    rooms(args: { app?: string; username: string }): Promise<AppGuestRooms>
    /** Set one guest's rooms on this App, within the rooms the App may hand out and never above the guest's role; idempotent, audited. This computer only. cap guests:rooms · portable · guests-rooms-v1. e.g. `await k2.asApp().guests.setRooms({username: 'dana', rooms: ['acme']})` */
    setRooms(args: { app?: string; rooms: string[]; username: string }): Promise<AppGuestRooms>
  }
  readonly room: {
    /** Who holds a grant on the room: guests and agent logins with their roles (from grants, not presence); admins of this box are one line. This computer only. cap room:members · portable · room-members-v1. e.g. `const {members} = await k2.room.members({workspace})` */
    members(args: { app?: string; workspace: string }): Promise<RoomMembers>
  }
  /** Any widget verb by name; a refused call rejects with K2Error. */
  call<V extends K2CallVerb>(verb: V, ...args: K2Verbs[V]['args']): Promise<K2Verbs[V]['value']>
  /** Subscribe by name; returns the unsubscribe. A refused subscription ends and calls `onError` (the function after `cb`) once with a K2Error; with no `onError` K2 logs it as an uncaught error. */
  subscribe<V extends K2SubscribeVerb>(
    verb: V,
    ...args:
      | [...K2Verbs[V]['args'], (value: K2Verbs[V]['value']) => void]
      | [...K2Verbs[V]['args'], (value: K2Verbs[V]['value']) => void, (error: K2Error) => void]
  ): () => void
  /** Alias of `subscribe`. */
  on: K2['subscribe']
  /** Resolves with the hello once K2 connects the frame (on its load, after your top-level script runs); rejects with K2Error `failed` "not connected" after 10 s. Await it before `can`, `config`, `widget` or `motion`: until then they read as empty. Calls wait for it on their own. */
  readonly connected: Promise<K2Hello>
  /** Drawing advice: the verb exists, its cap was allowed and K2 here has its feature. False until `connected` resolves. K2 still checks every call. */
  can(verb: string): boolean
  /** Tell K2 you have drawn (call once). */
  ready(): void
  /** The placement's `config` table from the Garden file (empty until `connected`). */
  readonly config: Readonly<Record<string, string | number | boolean>>
  /** A file in the widget's folder as a data: URL, or null. */
  asset(name: string): string | null
  readonly motion: { readonly reduced: boolean }
  /** Guards for data you didn't make. */
  readonly shape: K2Shape
  /** The error class (for `instanceof`). */
  readonly K2Error: { new (wire: { code: K2ErrorCode; message: string }, verb: string): K2Error }
  /** The codes worth retrying unchanged. */
  readonly retryable: readonly K2ErrorCode[]
}

declare global {
  const k2: K2
  interface Window {
    readonly k2: K2
  }
}
